<?php
require_once __DIR__.'/../includes/bootstrap.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.category_id=p.category_id WHERE p.product_id=? AND p.status='ACTIVE'");$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Product not found.');}$title=$p['product_name'];
if(customer_logged_in()){try{$pdo->prepare('INSERT INTO recently_viewed(customer_id,product_id) VALUES(?,?) ON DUPLICATE KEY UPDATE viewed_at=CURRENT_TIMESTAMP')->execute([$_SESSION['customer_id'],$id]);}catch(Throwable $ignore){}}
$commentErrors=[];$commentMsg='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['comment_action'])){require_customer();check_csrf();$rating=max(1,min(5,(int)$_POST['rating']));$comment=trim((string)$_POST['comment']);$s=$pdo->prepare("SELECT COUNT(*) FROM order_items oi JOIN orders o ON o.order_id=oi.order_id WHERE o.customer_id=? AND oi.product_id=? AND o.status='DELIVERED'");$s->execute([$_SESSION['customer_id'],$id]);if(!(int)$s->fetchColumn())$commentErrors[]='Only customers with a delivered order for this product can post a verified experience.';elseif($comment==='')$commentErrors[]='Please write a comment.';else{$q=$pdo->prepare('SELECT review_id FROM product_reviews WHERE product_id=? AND customer_id=? LIMIT 1');$q->execute([$id,$_SESSION['customer_id']]);$rid=$q->fetchColumn();if($rid){$pdo->prepare("UPDATE product_reviews SET rating=?,comment=?,status='PENDING',admin_reply=NULL,admin_reply_at=NULL WHERE review_id=?")->execute([$rating,$comment,(int)$rid]);}else{$pdo->prepare("INSERT INTO product_reviews(product_id,customer_id,rating,comment,status) VALUES(?,?,?,?, 'PENDING')")->execute([$id,$_SESSION['customer_id'],$rating,$comment]);}$commentMsg='Your experience was submitted for approval.';}}
$r=$pdo->prepare("SELECT r.*,c.full_name FROM product_reviews r JOIN customers c ON c.customer_id=r.customer_id WHERE r.product_id=? AND r.status='APPROVED' ORDER BY r.created_at DESC");$r->execute([$id]);$reviews=$r->fetchAll();$wished=false;if(customer_logged_in()){try{$s=$pdo->prepare('SELECT wishlist_id FROM wishlists WHERE customer_id=? AND product_id=?');$s->execute([$_SESSION['customer_id'],$id]);$wished=(bool)$s->fetch();}catch(Throwable $ignore){}}
require __DIR__.'/../includes/header.php';?><section class="detail"><div class="detail-image"><img src="<?=e(product_image($p))?>" alt="<?=e($p['product_name'])?>"></div><div class="detail-info"><span class="eyebrow"><?=e($p['category_name']??'Product')?> · <?=e($p['brand']??'')?></span><h1><?=e($p['product_name'])?></h1><div class="rating">★ <?=number_format((float)$p['rating'],1)?> (<?=count($reviews)?> reviews)</div><div class="detail-price"><?=money((float)$p['unit_price'])?> <?php if($p['compare_at_price']): ?><del><?=money((float)$p['compare_at_price'])?></del><?php endif; ?></div><p><?=e($p['description'])?></p><div id="liveStock" class="stock <?=((int)$p['quantity_in_stock'])>0?'in':'out'?>" data-product-id="<?=$id?>"><?=((int)$p['quantity_in_stock'])>0?'IN STOCK':'OUT OF STOCK'?> · <?= (int)$p['quantity_in_stock']?> available</div><?php if((int)$p['quantity_in_stock']>0): ?><div class="product-choice-panel"><div class="choice-title"><strong>Choose an action</strong><span>Call customer care or continue directly to checkout.</span></div><div class="product-actions product-choice-actions"><a class="btn call-product" href="tel:<?=e(customer_care_phone())?>"><?php echo contact_icon('phone'); ?> CALL</a><?php if(customer_logged_in()): ?><a class="btn primary checkout-product" href="/shop/buy-now.php?id=<?=$id?>"><?php echo nav_icon('shop'); ?> CHECKOUT</a><?php else: ?><a class="btn primary checkout-product" href="/auth/customer-login.php?next=<?=urlencode('/shop/buy-now.php?id='.$id)?>">SIGN IN TO CHECKOUT</a><?php endif; ?><form action="/customer/wishlist.php" method="post"><?=csrf_field()?><input type="hidden" name="product_id" value="<?=$id?>"><button class="btn ghost"><?= $wished?'♥ Saved':'♡ Add to wishlist' ?></button></form></div></div><?php elseif((int)$p['quantity_in_stock']<=0): ?><div class="product-choice-panel unavailable-choice"><strong>OUT OF STOCK</strong><span>This item cannot be checked out until management restores stock.</span><a class="btn call-product" href="tel:<?=e(customer_care_phone())?>"><?php echo contact_icon('phone'); ?> CALL CUSTOMER CARE</a></div><?php endif; ?></div></section>
<section class="reviews"><div class="section-head"><div><span class="eyebrow">PUBLIC CUSTOMER EXPERIENCE</span><h2>Comments & reviews</h2></div><span><?=count($reviews)?> approved comment(s)</span></div><?php if($commentMsg): ?><div class="flash success"><?=e($commentMsg)?></div><?php endif; ?><?php foreach($commentErrors as $x): ?><div class="errors"><?=e($x)?></div><?php endforeach; ?><?php if(customer_logged_in()): ?><div class="panel comment-form-panel"><h3>Share your experience</h3><p class="muted">Your comment becomes public after management approval.</p><form method="post" class="form"><?=csrf_field()?><input type="hidden" name="comment_action" value="1"><label>Rating<select name="rating"><option value="5">★★★★★ Excellent</option><option value="4">★★★★ Very good</option><option value="3">★★★ Good</option><option value="2">★★ Fair</option><option value="1">★ Poor</option></select></label><label>Your comment<textarea name="comment" required maxlength="2000" placeholder="Tell other shoppers about your experience..."></textarea></label><button class="btn primary">Post comment for approval</button></form></div><?php else: ?><div class="panel"><strong>Want to share your experience?</strong><p>Sign in to post a comment on this product.</p><a class="btn primary" href="/auth/customer-login.php?next=<?=urlencode('/shop/product.php?id='.$id)?>">Sign in to comment</a></div><?php endif; ?><?php foreach($reviews as $rv): ?><article class="review public-review"><div class="review-top"><strong><?=e($rv['full_name'])?></strong><span>★ <?=e((string)$rv['rating'])?></span></div><small>Verified customer experience · <?=e($rv['created_at'])?></small><p><?=nl2br(e($rv['comment']))?></p><?php if(!empty($rv['admin_reply'])): ?><div class="admin-reply"><strong>Shadril Shopping Store — Management reply</strong><p><?=nl2br(e($rv['admin_reply']))?></p><small><?=e($rv['admin_reply_at']??'')?></small></div><?php endif; ?></article><?php endforeach; ?><?php if(!$reviews): ?><div class="empty">No approved comments yet. Be the first verified customer to share an experience.</div><?php endif; ?></section><script>document.addEventListener('DOMContentLoaded',function(){const box=document.getElementById('liveStock');if(!box)return;const id=box.dataset.productId;async function sync(){try{const r=await fetch('/shop/live-stock.php?id='+encodeURIComponent(id),{cache:'no-store',credentials:'same-origin'});const j=await r.json();const d=j.products&&j.products[id];if(!d)return;box.textContent=(d.available?'IN STOCK':'OUT OF STOCK')+' · '+d.quantity+' available';box.classList.toggle('in',d.available);box.classList.toggle('out',!d.available);const actions=document.querySelector('.product-choice-actions');if(actions){const checkout=actions.querySelector('.checkout-product');if(!d.available&&checkout)checkout.remove();}}catch(e){}}sync();setInterval(sync,30000);});</script><?php require __DIR__.'/../includes/footer.php'; ?>